      "id": "SF10",
      "fonte": "Scopus",
      "topico": "Modelos Pedagógicos, Aprendizagem Híbrida e EAD",
      "titulo": "Virtualização de Laboratórios e Ambientes Imersivos - Incertezas de Viabilidade Regulatória e Eficácia Prática",
      "descricao": "Identifica-se um movimento incipiente voltado à virtualização de infraestruturas laboratoriais (substituição de bancadas físicas, equipamentos de ensaio e maquinários pesados por softwares de simulação digital em nuvem, máquinas virtuais remotas e ambientes interativos 3D), permitindo que os estudantes executem experimentos práticos de exatas, computação e engenharias diretamente pelo computador (151, 168). Embora os primeiros experimentos demonstrem viabilidade técnica e apontem para uma redução substancial dos custos de aquisição e manutenção de infraestrutura predial em instituições com restrições orçamentárias (168, 286), o desenvolvimento desse modelo e sua adoção em larga escala permanecem cercados de incertezas (151, 286). Persistem dúvidas sobre a equivalência formativa na aquisição de destreza manual e habilidades operacionais práticas, somadas a fortes resistências corporativas de conselhos profissionais e barreiras regulatórias do MEC, que hesitam em validar cargas horárias práticas puramente digitais em substituição às bancadas físicas presenciais (151).",
      "descricaoApa": "Identifica-se um movimento incipiente voltado à virtualização de infraestruturas laboratoriais (a substituição de bancadas físicas, equipamentos de ensaio e maquinários pesados por softwares de simulação digital em nuvem, máquinas virtuais remotas e ambientes interativos 3D), permitindo que os estudantes executem experimentos práticos de exatas, computação e engenharias diretamente pelo computador (Bhat et al., 2022; Delgado, 2021). Embora os primeiros experimentos demonstrem viabilidade técnica e apontem para uma redução substancial dos custos de aquisição e manutenção de infraestrutura predial em instituições com restrições orçamentárias (Bhat et al., 2022; Shaban et al., 2026), o desenvolvimento desse modelo e sua adoção em larga escala permanecem cercados de incertezas (Delgado, 2021; Shaban et al., 2026). Persistem dúvidas sobre a equivalência formativa na aquisição de destreza manual e habilidades operacionais práticas, somadas a fortes resistências corporativas de conselhos profissionais e barreiras regulatórias do MEC, que hesitam em validar cargas horárias práticas puramente digitais em substituição às bancadas físicas presenciais (Delgado, 2021).",
      "classificacao": "Incerteza",
