      "implicacoes": "A incerteza sobre a equivalência formativa e a autorização legal da simulação laboratorial impõe cautela na alocação de capital; uma aposta prematura na substituição física pode acarretar descredenciamento de cursos e vetos de conselhos de classe, enquanto a negligência frente às tecnologias imersivas arrisca encarecer a estrutura de custos frente a competidores que validem modelos híbridos; a estratégia institucional dependerá de adotar a simulação como reforço pedagógico complementar, acompanhando a evolução dos marcos regulatórios do MEC.",
