      "title": "Principles and Approach Towards Sustainability in Higher Education Institutions",
      "year": 2024,
      "sourceTitle": "Role of Science and Technology for Sustainable Future: Sustainable Development: a Primary Goal: Volume 1",
      "doi": "10.1007/978-981-97-0710-2_24",
      "doiLink": "https://doi.org/10.1007/978-981-97-0710-2_24",
      "abstract": "The utilization of sustainable technologies and practices is more relevant than ever before. This article highlights the basic principles of sustainability and the need for adoption by higher education institutions. The United Nations’ global sustainability goals are also discussed. Several strategies on how the HEIs can implement the sustainability goals are presented to assist decision-making for HEIs who wish to align itself towards sustainability. © The Editor(s) (if applicable) and The Author(s), under exclusive license to Springer Nature Singapore Pte Ltd. 2024.",
